SELECT DISTINCTROW [Gesamt Normierung Zeitraum].Datum, Avg([Gesamt Normierung Zeitraum].[I Gesamt]) AS [Mittelwert von I Gesamt], Avg([Gesamt Normierung Zeitraum].i) AS [Mittelwert von i], Avg([Gesamt Normierung Zeitraum].Cc) AS [Mittelwert von Cc], Avg([Gesamt Normierung Zeitraum].[t An]) AS [Mittelwert von t An], Avg([Gesamt Normierung Zeitraum].[t Ka]) AS [Mittelwert von t Ka], Avg([Gesamt Normierung Zeitraum].tm) AS [Mittelwert von tm], Avg([Gesamt Normierung Zeitraum].Uo) AS [Mittelwert von Uo], Avg([Gesamt Normierung Zeitraum].Ui) AS [Mittelwert von Ui1], Avg([Gesamt Normierung Zeitraum].Un) AS [Mittelwert von Un], [Gesamt Normierung Zeitraum].iRef, Count([Gesamt Normierung Zeitraum].Position) AS [Anzahl von Position]
FROM tblGewDaten, [Gesamt Normierung Zeitraum]
GROUP BY [Gesamt Normierung Zeitraum].Datum, [Gesamt Normierung Zeitraum].iRef;
